function DescendingSort(lst: array of integer): array of integer;
begin
  var n := lst.Length;
  for var i := 0 to n - 1 do
    for var j := 0 to n - i - 2 do
      if lst[j] < lst[j + 1] then
      begin
        var temp := lst[j];
        lst[j] := lst[j + 1];
        lst[j + 1] := temp;
      end;
  Result := lst;
end;

procedure DFS(sublist: System.Collections.IList; var currentDepth : integer; var maxDepth : integer);
begin
  currentDepth += 1;
  for var i := 0 to sublist.Count - 1 do
    if sublist[i] is System.Collections.IList then
      DFS(System.Collections.IList(sublist[i]), currentDepth, maxDepth);
  maxDepth := Max(maxDepth, currentDepth);
  currentDepth -= 1;
end;

function FindMaxNestedSublists(lst: System.Collections.IList): integer;
