function MergeSort(var arr: array of integer; start, &end: integer): integer;
begin
  if start >= &end then
  begin
    Result := 0;
    exit;
  end;

  var mid := (start + &end) div 2;
  var count := MergeSort(arr, start, mid) + MergeSort(arr, mid + 1, &end);

  var i := start;
  var j := mid + 1;
  var temp := new List<integer>;

  while (i <= mid) and (j <= &end) do
  begin
    if arr[i] <= arr[j] then
    begin
      temp.Add(arr[i]);
      i += 1;
    end
    else
    begin
      temp.Add(arr[j]);
      count += mid - i + 1;
      j += 1;
    end;
  end;

  while i <= mid do
  begin
    temp.Add(arr[i]);
    i += 1;
  end;

  while j <= &end do
  begin
    temp.Add(arr[j]);
    j += 1;
  end;

  for var k := 0 to temp.Count - 1 do
    arr[start + k] := temp[k];

  Result := count;
end;

