function SortMatrix(matrix: array of array of integer): array of array of integer;
begin
  var rowCount := matrix.Length;
  var colCount := matrix[0].Length;

  for var i := 0 to rowCount - 1 do
    &Array.Sort(matrix[i]);

  for var j := 0 to colCount - 1 do
  begin
    var column := new List<integer>;
    for var i := 0 to rowCount - 1 do
      column.Add(matrix[i][j]);

    column.Sort();

    for var i := 0 to rowCount - 1 do
      matrix[i][j] := column[i];
  end;

  Result := matrix;
end;

function CountUniquePathsObstacles(obstacleGrid: array [,] of integer): integer;
begin
  var m := obstacleGrid.GetLength(0);
  var n := obstacleGrid.GetLength(1);
  var dp := new integer[m, n];

  if obstacleGrid[0, 0] = 0 then
    dp[0, 0] := 1;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if (obstacleGrid[i, j] = 0) and ((i > 0) or (j > 0)) then
      begin
        if (i > 0) and (j > 0) then
          dp[i, j] := dp[i - 1, j] + dp[i, j - 1]
        else if i > 0 then
          dp[i, j] := dp[i - 1, j]
        else
          dp[i, j] := dp[i, j - 1];
      end;

  Result := dp[m - 1, n - 1];
end;

