function DivideArray(arr: array of integer): boolean;
begin
  var total := arr.Sum;
  if total mod 2 <> 0 then
  begin
    Result := false;
    exit;
  end;

  var target := total div 2;
  var dp := new boolean[target + 1];
  dp[0] := true;

  for var i := 0 to arr.Length - 1 do
