function MatrixReshape(mat: array [,] of integer; r, c: integer): array [,] of integer;
begin
  var m := mat.GetLength(0);
  var n := mat.GetLength(1);

  if m * n <> r * c then
  begin
    Result := mat;
    exit;
  end;

  var output := new integer[r, c];
  var x := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      output[x div c, x mod c] := mat[i, j];
      x += 1;
    end;

  Result := output;
end;

function NChooseK(n, k: integer): integer;
begin
  if k > n then
  begin
    Result := 0;
    exit;
  end;

  if (k = 0) or (k = n) then
  begin
    Result := 1;
    exit;
  end;

  k := Min(k, n - k);
  var numerator := 1;

  for var i := n downto n - k + 1 do
    numerator := numerator * i;

  var denominator := 1;
  for var i := 1 to k do
    denominator := denominator * i;

  Result := numerator div denominator;
end;

