  if nums1.Length < nums2.Length then
  begin
    var temp := nums1;
    nums1 := nums2;
    nums2 := temp;
  end;

  var deque1 := new Queue<integer>(nums1);
  var deque2 := new Queue<integer>(nums2);

  for var i := 1 to nums2.Length - 1 do
  begin
    deque1.Enqueue(-1);
    deque1.Enqueue(-1);
  end;
  deque1.Enqueue(-1);

  for var i := 0 to deque1.Count - nums2.Length do
  begin
    deque1.Dequeue;
    var count := 0;
    var flag := false;

    for var j := 0 to nums2.Length - 1 do
    begin
      if deque1.ElementAt(j) = deque2.ElementAt(j) then
      begin
        if not flag then
          flag := true;
        count += 1;
      end
      else
      begin
        count := 0;
        flag := false;
      end;
      answer := Max(answer, count);
    end;
  end;

