      while left < right do
      begin
        var total := nums[idx] + nums[left] + nums[right];
        if Abs(closest - target) > Abs(total - target) then
          closest := total;

        if total > target then
          right -= 1
        else if total < target then
          left += 1
        else
        begin
          Result := target;
          exit;
        end;
      end;
    end;
  end;

  Result := closest;
end;

