    count1[Ord(s1[i]) - Ord('a')] += 1;

  for var i := 0 to s2.Length - 1 do
    count2[Ord(s2[i]) - Ord('a')] += 1;

  for var i := 0 to 25 do
    res += Abs(count1[i] - count2[i]);

  Result := res;
end;

function ThreeSumCount(nums: array of integer): integer;
begin
  &Array.Sort(nums);
  var count := 0;

  for var i := 0 to nums.Length - 3 do
  begin
    if (i > 0) and (nums[i] = nums[i - 1]) then
      continue;

    var left := i + 1;
    var right := nums.Length - 1;

    while left < right do
    begin
      var s := nums[i] + nums[left] + nums[right];
      if s < 0 then
        left += 1
      else if s > 0 then
        right -= 1
      else
      begin
        count += 1;
        while (left < right) and (nums[left] = nums[left + 1]) do
          left += 1;
        while (left < right) and (nums[right] = nums[right - 1]) do
          right -= 1;
        left += 1;
        right -= 1;
      end;
    end;
  end;

  Result := count;
end;

