uses System.Collections.Generic;

function IsAcyclic(numNodes: integer; edgesList: List<(integer, integer)>): boolean;
begin
  var graph := new Dictionary<integer, List<integer>>;
  var indegree := new integer[numNodes];

  for var i := 0 to numNodes - 1 do
    graph[i] := new List<integer>;

  foreach var edge in edgesList do
  begin
    graph[edge[0]].Add(edge[1]);
    indegree[edge[1]] += 1;
  end;

  var queue := new Queue<integer>;
  for var node := 0 to numNodes - 1 do
    if indegree[node] = 0 then
      queue.Enqueue(node);

  var visited := 0;

  while queue.Count > 0 do
  begin
    var node := queue.Dequeue;
    visited += 1;

    foreach var neighbor in graph[node] do
    begin
      indegree[neighbor] -= 1;
      if indegree[neighbor] = 0 then
        queue.Enqueue(neighbor);
    end;
  end;

  Result := visited = numNodes;
end;

function LeastBricks(wall: List<List<integer>>): integer;
begin
  var numRows := wall.Count;
  var minBricks := numRows;
  var edgesAt := new Dictionary<integer, integer>;
  var wallWidth := 0;

  if (wall[0].Count = 1) and (wall[0][0] = 1) then
  begin
    Result := numRows;
    exit;
  end;

  foreach var row in wall do
  begin
    var position := 0;
    for var i := 0 to row.Count - 2 do
    begin
      position += row[i];
      if not edgesAt.ContainsKey(position) then
        edgesAt[position] := 0;
      edgesAt[position] += 1;
    end;
    if wallWidth = 0 then
      wallWidth := position + row[row.Count - 1];
  end;

  foreach var position in edgesAt.Keys do
  begin
    if (position > 0) and (position < wallWidth) then
    begin
      var bricksCrossed := numRows - edgesAt[position];
      minBricks := Min(minBricks, bricksCrossed);
    end;
  end;

  Result := minBricks;
end;

function MinDelToMakeEqual(str1, str2: string): integer;
begin
  var m := str1.Length;
  var n := str2.Length;
  var dp := new integer[m + 1, n + 1];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if str1[i] = str2[j] then
        dp[i + 1, j + 1] := dp[i, j] + 1
      else
        dp[i + 1, j + 1] := Max(dp[i + 1, j], dp[i, j + 1]);
    end;

  Result := m - dp[m, n] + n - dp[m, n];
end;

function RearrangeCharacters(s, target: string): integer;
begin
  var ans := integer.MaxValue;
  var cnt := new Dictionary<char, integer>;
  var targetCnt := new Dictionary<char, integer>;

  for var i := 0 to s.Length - 1 do
  begin
    if not cnt.ContainsKey(s[i]) then
      cnt[s[i]] := 0;
    cnt[s[i]] += 1;
  end;

  for var i := 0 to target.Length - 1 do
  begin
    if not targetCnt.ContainsKey(target[i]) then
      targetCnt[target[i]] := 0;
    targetCnt[target[i]] += 1;
  end;

  foreach var pair in targetCnt do
  begin
    if not cnt.ContainsKey(pair.Key) then
    begin
      Result := 0;
      exit;
    end;
    ans := Min(ans, cnt[pair.Key] div pair.Value);
  end;

  Result := ans;
end;

