function FindFirstOccurrence(nums: array of integer; target: integer; startIdx, endIdx: integer): integer;
begin
  var left := startIdx;
  var right := endIdx;
  while left < right do
  begin
    var mid := left + (right - left) div 2;
    if nums[mid] < target then
      left := mid + 1
    else
      right := mid;
  end;
  if nums[left] = target then
    Result := left
  else
    Result := -1;
end;

function FindLastOccurrence(nums: array of integer; target: integer; startIdx, endIdx: integer): integer;
begin
  var left := startIdx;
  var right := endIdx;
  while left < right do
  begin
    var mid := left + (right - left + 1) div 2;
    if nums[mid] > target then
      right := mid - 1
    else
      left := mid;
  end;
  if nums[right] = target then
    Result := right
  else
    Result := -1;
end;

function CountTargetOccurrences(nums: array of integer; target: integer): integer;
begin
  var firstOccurrence := FindFirstOccurrence(nums, target, 0, nums.Length - 1);
  if firstOccurrence = -1 then
  begin
    Result := 0;
    exit;
  end;

  var lastOccurrence := FindLastOccurrence(nums, target, firstOccurrence, nums.Length - 1);
  Result := lastOccurrence - firstOccurrence + 1;
end;

function ValidParenthesesSequences(n: integer): integer;
