function ValidParenthesis(parenthesisList: array of string): boolean;
begin
  var stack := new Stack<string>;

  for var i := 0 to parenthesisList.Length - 1 do
  begin
    if parenthesisList[i] = '(' then
      stack.Push('(')
    else if parenthesisList[i] = ')' then
    begin
      if stack.Count > 0 then
        stack.Pop
      else
      begin
        Result := false;
        exit;
      end;
    end;
  end;

  Result := stack.Count = 0;
end;

function Factorial(memo: Dictionary<integer, integer>; n: integer): integer;
begin
  if n = 0 then
  begin
    Result := 1;
    exit;
  end;

  if memo.ContainsKey(n) then
    Result := memo[n]
    else
  begin
    var num := n * Factorial(memo, n - 1);
    memo[n] := num;
    Result := num;
  end;
end;

