function LongestSubarray(nums: array of integer): integer;
begin
  var left := 0;
  var zeroCount := 0;
  var maxLen := 0;

  for var right := 0 to nums.Length - 1 do
  begin
    if nums[right] = 0 then
      zeroCount += 1;

    while zeroCount > 1 do
    begin
      if nums[left] = 0 then
        zeroCount -= 1;
      left += 1;
    end;

    maxLen := Max(maxLen, right - left);
  end;

  Result := maxLen;
end;

function HasSubstrMatch(A, B: array of integer; k: integer): boolean;
begin
  if k = 0 then
  begin
    Result := true;
    exit;
  end;

  var hash2inds := new Dictionary<integer, List<integer>>;

  for var i := 0 to A.Length - k do
  begin
    var subA := A[i:i + k];
    var hash := subA.GetHashCode;

    if not hash2inds.ContainsKey(hash) then
      hash2inds[hash] := new List<integer>;
    hash2inds[hash].Add(i);
  end;

  for var j := 0 to B.Length - k do
  begin
    var subB := B[j:j + k];
    var hash := subB.GetHashCode;

    if hash2inds.ContainsKey(hash) then
    begin
      foreach var i in hash2inds[hash] do
        if A[i:i + k].SequenceEqual(subB) then
        begin
          Result := true;
          exit;
        end;
    end;
  end;

  Result := false;
end;

function FindMaxSubarrayLength(A, B: array of integer): integer;
begin
  var lo := 0;
  var hi := Min(A.Length, B.Length) + 1;

  while lo < hi do
  begin
    var k := (lo + hi) div 2;
    if HasSubstrMatch(A, B, k) then
      lo := k + 1
    else
      hi := k;
  end;

  Result := lo - 1;
end;

function LongestZigzag(nums: array of integer): integer;
begin
  if nums.Length < 2 then
  begin
    Result := nums.Length;
    exit;
  end;

  var up := new integer[nums.Length];
  var down := new integer[nums.Length];

  for var i := 0 to nums.Length - 1 do
  begin
    up[i] := 1;
    down[i] := 1;
  end;

  for var i := 1 to nums.Length - 1 do
  begin
    if nums[i] > nums[i - 1] then
      up[i] := down[i - 1] + 1
    else if nums[i] < nums[i - 1] then
      down[i] := up[i - 1] + 1;
  end;

  Result := Max(up.Max, down.Max);
end;

