  for var i := N - 1 downto 0 do
  begin
    dp[i, i] := 1;
    for var j := i + 1 to N - 1 do
    begin
      if s[i] = s[j] then
        dp[i, j] := dp[i + 1, j - 1] + 2
      else
        dp[i, j] := Max(dp[i + 1, j], dp[i, j - 1]);
    end;
  end;

  Result := dp[0, N - 1];
end;

