  dp[0] := 1;
  var sPtr := 0;

  while sPtr < s.Length do
  begin
    for var tPtr := t.Length - 1 downto 0 do
    begin
      if s[sPtr] = t[tPtr] then
        dp[tPtr + 1] += dp[tPtr];
    end;
    sPtr += 1;
  end;

  Result := dp[t.Length];
end;

