function Check234Pattern(nums: array of integer): boolean;
begin
  var deq := new Stack<integer>;
  var num2 := -1;

  for var i := nums.Length - 1 downto 0 do
  begin
    if (num2 <> -1) and (nums[i] < num2) then
    begin
      Result := true;
      exit;
    end;

    while (deq.Count > 0) and (deq.Peek < nums[i]) do
      num2 := deq.Pop;

    deq.Push(nums[i]);
  end;

  Result := false;
end;

