function MaxTurbulenceSize(arr: array of integer): integer;
begin
  if arr.Length < 2 then
  begin
    Result := arr.Length;
    exit;
  end;

  var maximum := 1;
  var startIdx := 0;
  var &end := 0;
  var N := arr.Length;

  while startIdx + 1 < N do
  begin
    if arr[startIdx] = arr[startIdx + 1] then
    begin
      startIdx += 1;
      continue;
    end;

    &end := startIdx + 1;
    while (&end + 1 < N) and IsCurrIndexTurbulent(arr, &end) do
      &end += 1;

    maximum := Max(maximum, &end - startIdx + 1);
    startIdx := &end;
  end;

  Result := maximum;
end;

