function ValidParenthesesSequence(s: string): boolean;
begin
  var mapping := new Dictionary<char, char>;
  mapping[')'] := '(';
  mapping[']'] := '[';
  mapping['}'] := '{';

  var stack := new Stack<char>;

  for var i := 0 to s.Length - 1 do
  begin
    if mapping.ContainsValue(s[i]) then
      stack.Push(s[i])
    else if mapping.ContainsKey(s[i]) then
    begin
      if (stack.Count = 0) or (mapping[s[i]] <> stack.Pop) then
      begin
        Result := false;
        exit;
      end;
    end
    else
    begin
      Result := false;
      exit;
    end;
  end;

  Result := stack.Count = 0;
end;

