function FindMinSquares(n: integer): integer;
begin
  var dp := new integer[n + 1];

  for var i := 1 to n do
  begin
    var minVal := integer.MaxValue;
    var j := 1;
    while j * j <= i do
    begin
      minVal := Min(minVal, dp[i - j * j] + 1);
      j += 1;
    end;
    dp[i] := minVal;
  end;

  Result := dp[n];
end;

function MinOperationsMaxProfit(customers: array of integer; boardingCost, runningCost: integer): integer;
begin
  var remainingCustomers := 0;
  var customersServed := 0;
  var rotation := 0;
  var maxProfit := -1;
  var resultVal := 0;
  var i := 0;

  while (remainingCustomers > 0) or (i < customers.Length) do
  begin
    rotation += 1;
    if i < customers.Length then
      remainingCustomers += customers[i];

    if remainingCustomers < 4 then
    begin
      customersServed += remainingCustomers;
      remainingCustomers := 0;
    end
    else
    begin
      customersServed += 4;
      remainingCustomers -= 4;
    end;

    var profit := customersServed * boardingCost - rotation * runningCost;
    if maxProfit < profit then
    begin
      maxProfit := profit;
      resultVal := rotation;
    end;
    i += 1;
  end;

  if maxProfit <= 0 then
    Result := -1
  else
    Result := resultVal;
end;

