end;

type
  ListNode = class
    val: integer;
    next: ListNode;

    constructor Create(x: integer);
    begin
      val := x;
      next := nil;
    end;
  end;

function CreateLinkedList(lst: array of integer): ListNode;
begin
  if lst.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var head := new ListNode(lst[0]);
  var current := head;

  for var i := 1 to lst.Length - 1 do
  begin
    current.next := new ListNode(lst[i]);
    current := current.next;
  end;

  Result := head;
end;

function PartitionList(head: ListNode; x: integer): ListNode;
begin
  var leftHead := new ListNode(0);
  var left := leftHead;
  var rightHead := new ListNode(0);
  var right := rightHead;
  var current := head;

  while current <> nil do
  begin
    if current.val < x then
    begin
      left.next := current;
      left := left.next;
    end
    else
    begin
      right.next := current;
      right := right.next;
    end;
    current := current.next;
  end;

  left.next := rightHead.next;
  right.next := nil;
  Result := leftHead.next;
end;

function LinkedListToList(head: ListNode): array of integer;
begin
  var lst := new List<integer>;
  var current := head;

  while current <> nil do
  begin
    lst.Add(current.val);
    current := current.next;
  end;

  Result := lst.ToArray;
end;

function PartitionLinkedList(lst: array of integer; x: integer): array of integer;
begin
  var head := CreateLinkedList(lst);
  var partitionedHead := PartitionList(head, x);
  Result := LinkedListToList(partitionedHead);
end;

function FindMinUniqueInts(arr: array of integer; k: integer): integer;
begin
  var counts := new Dictionary<integer, integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    if not counts.ContainsKey(arr[i]) then
      counts[arr[i]] := 0;
    counts[arr[i]] += 1;
  end;

  var freqs := new List<(integer, integer)>;
  foreach var pair in counts do
    freqs.Add((pair.Value, pair.Key));

  freqs.Sort((x, y) -> x[0].CompareTo(y[0]));
  var uniqueInts := freqs.Count;

  for var i := 0 to freqs.Count - 1 do
  begin
    if freqs[i][0] <= k then
    begin
      k -= freqs[i][0];
      uniqueInts -= 1;
    end
    else
      break;
  end;

  Result := uniqueInts;
end;

