  for var i := 0 to N - 1 do
  begin
    if S[i] <> S[N - 1 - i] then
    begin
      Result := -1;
      exit;
    end
    else if i = N - 1 - i then
    begin
      Result := i;
      exit;
    end;
  end;

  Result := -1;
end;

