function FindUniquePairs(arr: array of integer; target: integer): integer;
begin
  &Array.Sort(arr);
  var res := new HashSet<(integer, integer)>;
  var lo := 0;
  var hi := arr.Length - 1;

  while lo < hi do
  begin
    if arr[lo] + arr[hi] < target then
      lo += 1
    else if arr[lo] + arr[hi] > target then
      hi -= 1
    else
    begin
      res.Add((arr[lo], arr[hi]));
      lo += 1;
      hi -= 1;
    end;
  end;

  Result := res.Count;
end;

function MinOperationsToPermutation(target, arr: array of integer): integer;
begin
  var targetIndex := new Dictionary<integer, integer>;

  for var i := 0 to target.Length - 1 do
    targetIndex[target[i]] := i;

  var seq := new List<integer>;
  for var i := 0 to arr.Length - 1 do
    if targetIndex.ContainsKey(arr[i]) then
      seq.Add(targetIndex[arr[i]]);

  var lis := new List<integer>;
  for var i := 0 to seq.Count - 1 do
  begin
    var num := seq[i];
    var pos := lis.BinarySearch(num);
    if pos < 0 then
      pos := not pos;

    if pos = lis.Count then
      lis.Add(num)
    else
      lis[pos] := num;
  end;

  Result := target.Length - lis.Count;
end;

