procedure DFS(node: integer; var visited, onPath: array of boolean; edges: array of array of integer; var hasCycle: boolean);
begin
  if onPath[node] then
  begin
    hasCycle := true;
    exit;
  end;

  if visited[node] or hasCycle then
    exit;

  visited[node] := true;
  onPath[node] := true;

  for var i := 0 to edges.Length - 1 do
  begin
    if edges[i][0] = node then
      DFS(edges[i][1], visited, onPath, edges, hasCycle);
  end;

  onPath[node] := false;
end;

function DetectCycleDFS(edges: array of array of integer; numCourses: integer): boolean;
begin
