  var onPath := new boolean[numCourses];
  var hasCycle := false;

  for var i := 0 to numCourses - 1 do
  begin
    if not visited[i] then
      DFS(i, visited, onPath, edges, hasCycle);
  end;

  Result := hasCycle;
end;

function UniqueLongestSubstring(s: string): string;
begin
  var charSet := new HashSet<char>;
  var left := 0;
  var res := '';

  for var right := 0 to s.Length - 1 do
  begin
    while charSet.Contains(s[right]) do
    begin
      charSet.Remove(s[left]);
      left += 1;
    end;

    charSet.Add(s[right]);

    if res.Length < right - left + 1 then
      res := s.Substring(left, right - left + 1);
  end;

  Result := res;
end;

function GCD(a, b: integer): integer;
begin
  while b <> 0 do
  begin
    var temp := b;
    b := a mod b;
    a := temp;
  end;
