function JumpStairs(n: integer): integer;
begin
  if n <= 1 then
  begin
    Result := n;
    exit;
  end;

  var first := 1;
  var second := 2;
  var third := 4;

  for var i := 3 to n - 1 do
  begin
    var total := first + second + third;
    first := second;
    second := third;
    third := total;
  end;

  Result := third;
end;

function TrapRainwater(height: array of integer): integer;
begin
  if height.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var left := 0;
  var right := height.Length - 1;
  var maxLeft := height[left];
  var maxRight := height[right];
  var trappedWater := 0;

  while left < right do
  begin
    if maxLeft < maxRight then
    begin
      left += 1;
      maxLeft := Max(maxLeft, height[left]);
      trappedWater += maxLeft - height[left];
    end
    else
    begin
      right -= 1;
      maxRight := Max(maxRight, height[right]);
      trappedWater += maxRight - height[right];
    end;
  end;

  Result := trappedWater;
end;

function MinReorder(n: integer; connections: array of (integer, integer)): integer;
begin
  var edges := new Dictionary<integer, List<(integer, integer)>>;

  for var i := 0 to n - 1 do
    edges[i] := new List<(integer, integer)>;

  foreach var (src, dest) in connections do
  begin
    edges[src].Add((dest, 1));
    edges[dest].Add((src, 0));
  end;

  var q := new Queue<integer>;
  var visited := new HashSet<integer>;
  var changes := 0;

  q.Enqueue(0);
  visited.Add(0);

  while q.Count > 0 do
  begin
    var curr := q.Dequeue;

    foreach var (neiCity, cost) in edges[curr] do
    begin
      if not visited.Contains(neiCity) then
      begin
        visited.Add(neiCity);
        changes += cost;
        q.Enqueue(neiCity);
      end;
    end;
  end;

  Result := changes;
end;

function SlidingWindow(nums: array of integer; k: integer): array of integer;
begin
  var resultList := new List<integer>;

  if nums.Length = 0 then
  begin
    Result := resultList.ToArray;
    exit;
  end;

  var window := new List<integer>(nums[0:k]);
  var maxValue := window.Max;
  resultList.Add(maxValue);

  for var i := k to nums.Length - 1 do
  begin
    window.RemoveAt(0);
    window.Add(nums[i]);
    maxValue := Max(maxValue, nums[i]);

    if nums[i - k] = maxValue then
      maxValue := window.Max;

    resultList.Add(maxValue);
  end;

  Result := resultList.ToArray;
end;

