procedure Generate(start: integer; current: array of integer; resultList: List<array of integer>);
begin
  if start = current.Length then
  begin
    resultList.Add(current.ToArray()); 
    exit;
  end;

  for var i := start to current.Length - 1 do
  begin
    Swap(current[start], current[i]);
    Generate(start + 1, current, resultList);
    Swap(current[start], current[i]);
  end;
end;

