    var (x, y) := pairs[i];
    sim.Add((x, y));
    sim.Add((y, x));
  end;

  if words1.Length <> words2.Length then
  begin
    Result := false;
    exit;
  end;

  for var i := 0 to words1.Length - 1 do
  begin
    var x := words1[i];
    var y := words2[i];

    if (x <> y) and (not sim.Contains((x, y))) then
    begin
