function IsPrime(num: integer): boolean;
begin
  if num <= 1 then
  begin
    Result := false;
    exit;
  end;

  if num <= 3 then
  begin
    Result := true;
    exit;
  end;

  if (num mod 2 = 0) or (num mod 3 = 0) then
  begin
    Result := false;
    exit;
  end;

  var i := 5;
  while i * i <= num do
  begin
    if (num mod i = 0) or (num mod (i + 2) = 0) then
    begin
      Result := false;
      exit;
    end;
    i += 6;
  end;

  Result := true;
end;

