function TotalCost(costs: array of integer; k, candidates: integer): integer;
begin
  var minHeap := new SortedSet<(integer, integer)>;
  var seenIndex := new HashSet<integer>;
  var left := candidates - 1;
  var right := costs.Length - candidates;
  var res := 0;

  for var i := 0 to costs.Length - 1 do
  begin
    if (i <= candidates - 1) or (i >= costs.Length - candidates) then
    begin
      minHeap.Add((costs[i], i));
      seenIndex.Add(i);
    end;
  end;

  while k > 0 do
  begin
    var (cost, index) := minHeap.Min;
    minHeap.Remove(minHeap.Min);

    if (index <= left) and (left < right) and (not seenIndex.Contains(left + 1)) then
    begin
      left += 1;
      minHeap.Add((costs[left], left));
      seenIndex.Add(left);
    end
    else if (index >= right) and (left < right) and (not seenIndex.Contains(right - 1)) then
    begin
      right -= 1;
      minHeap.Add((costs[right], right));
      seenIndex.Add(right);
    end;

    res += cost;
    k -= 1;
  end;

  Result := res;
end;

function ConvertToBase3(n: integer): integer;
begin
  var base3 := '';

  while n > 0 do
  begin
    var remainder := n mod 3;
    base3 := remainder.ToString + base3;
    n := n div 3;
  end;

  if base3 = '' then
    Result := 0
  else
    Result := StrToInt(base3);
end;

