      var repeated := '';

      for var j := 1 to length div i do
        repeated += substr;

      if repeated = s then
      begin
        Result := i;
        exit;
      end;
    end;
  end;

  Result := length;
end;

function CalculateDeletions(str1, str2: string): integer;
begin
  var counter1 := new Dictionary<char, integer>;
  var counter2 := new Dictionary<char, integer>;

  for var i := 0 to str1.Length - 1 do
  begin
    if not counter1.ContainsKey(str1[i]) then
      counter1[str1[i]] := 0;
    counter1[str1[i]] += 1;
  end;

  for var i := 0 to str2.Length - 1 do
  begin
    if not counter2.ContainsKey(str2[i]) then
      counter2[str2[i]] := 0;
    counter2[str2[i]] += 1;
  end;

  var totalDeletions := 0;

  foreach var pair in counter1 do
  begin
    var char := pair.Key;
    if counter2.ContainsKey(char) then
      totalDeletions += Abs(pair.Value - counter2[char])
    else
      totalDeletions += pair.Value;
  end;

  foreach var pair in counter2 do
  begin
    var char := pair.Key;
    if not counter1.ContainsKey(char) then
      totalDeletions += pair.Value;
  end;

  Result := totalDeletions;
end;

