function CountNegatives(grid: array of array of integer): integer;
begin
  var res := 0;
  var nrows := grid.Length;
  var ncols := grid[0].Length;

  var startL := 0;
  var startR := nrows - 1;

  for var i := ncols - 1 downto 0 do
  begin
    var l := startL;
    var r := startR;

    while l <= r do
    begin
      var m := l + (r - l) div 2;
      if grid[m][i] >= 0 then
        l := m + 1
      else
        r := m - 1;
    end;

    res += nrows - l;
    startL := l;
  end;

  Result := res;
end;

function MinSwapsRequired(arr: array of integer): integer;
begin
  var n := arr.Length; 
  var arrPos := new System.Tuple<integer, integer>[n];

  for var i := 0 to n - 1 do
    arrPos[i] := (i, arr[i]);

  arrPos := arrPos.OrderBy(x -> x[1]).ToArray;
  var vis := new boolean[n];
  var ans := 0;

  for var i := 0 to n - 1 do
  begin
    if vis[i] or (arrPos[i][0] = i) then
      continue;

    var cycleSize := 0;
    var j := i;

    while not vis[j] do
    begin
      vis[j] := true;
      j := arrPos[j][0];
      cycleSize += 1;
    end;

    if cycleSize > 0 then
      ans += cycleSize - 1;
  end;

  Result := ans;
end;

function FindLongestCommonSubstring(str1, str2: string): string;
begin
  var m := str1.Length;
  var n := str2.Length;
  var dp := new integer[m + 1, n + 1];
  var longest := 0;
  var endIndex := 0;

  for var i := 1 to m do
    for var j := 1 to n do
    begin
      if str1[i - 1] = str2[j - 1] then
      begin
        dp[i, j] := dp[i - 1, j - 1] + 1;
        if dp[i, j] > longest then
        begin
          longest := dp[i, j];
          endIndex := i - 1;
        end;
      end
      else
        dp[i, j] := 0;
    end;

  if longest > 0 then
    Result := str1.Substring(endIndex - longest + 1, longest)
  else
    Result := '';
end;

function IsInterleave(s1, s2, s3: string): boolean;
begin
  if s1.Length + s2.Length <> s3.Length then
  begin
    Result := false;
    exit;
  end;

  var dp := new boolean[s1.Length + 1, s2.Length + 1];
  dp[0, 0] := true;

  for var i := 0 to s1.Length do
    for var j := 0 to s2.Length do
    begin
      if i > 0 then
        dp[i, j] := dp[i, j] or (dp[i - 1, j] and (s1[i - 1] = s3[i + j - 1]));

      if j > 0 then
        dp[i, j] := dp[i, j] or (dp[i, j - 1] and (s2[j - 1] = s3[i + j - 1]));
    end;

  Result := dp[s1.Length, s2.Length];
end;

