function IsPerfectPower(n: integer): boolean;
begin
  if n < 2 then
  begin
    Result := false;
    exit;
  end;

  for var base := 2 to Trunc(Sqrt(n)) do
  begin
    var pow := 2;
    while Power(base, pow) <= n do
    begin
      if Power(base, pow) = n then
      begin
        Result := true;
        exit;
      end;
      pow += 1;
    end;
  end;

  Result := false;
end;

function CountRotations(arr: array of integer): integer;
begin
  var low := 0;
  var high := arr.Length - 1;

  while low <= high do
  begin
    if arr[low] <= arr[high] then
    begin
      Result := low;
      exit;
    end;

    var mid := (low + high) div 2;
    var next := (mid + 1) mod arr.Length;
    var prev := (mid - 1 + arr.Length) mod arr.Length;

    if (arr[mid] <= arr[next]) and (arr[mid] <= arr[prev]) then
    begin
      Result := mid;
      exit;
    end
    else if arr[mid] <= arr[high] then
      high := mid - 1
    else
      low := mid + 1;
  end;

  Result := 0;
end;

function Solve(k, moves: integer): integer;
begin
  var dp := new integer[k + 1, moves + 1];

  for var i := 1 to k do
    for var j := 1 to moves do
      dp[i, j] := 1 + dp[i - 1, j - 1] + dp[i, j - 1];

  Result := dp[k, moves];
end;

function SuperEggDrop(K, N: integer): integer;
begin
  var left := 1;
  var right := N + 1;

  while left < right do
  begin
    var mid := (left + right) div 2;
    if Solve(K, mid) >= N then
      right := mid
    else
      left := mid + 1;
  end;

  Result := left;
end;

