function ZigzagEncode(s: string; numRows: integer): string;
begin
  if numRows = 1 then
  begin
    Result := s;
    exit;
  end;

  var rows := new string[numRows];
  var incVal := 1;
  var rowIndex := 0;

  for var i := 0 to s.Length - 1 do
  begin
    rows[rowIndex] += s[i];

    if (rowIndex = numRows - 1) or ((i <> 0) and (rowIndex = 0)) then
      incVal := -incVal;

    rowIndex += incVal;
  end;

  Result := string.Join('', rows);
end;

function CountSubArraysWithSum(arr: array of integer; targetSum: integer): integer;
begin
  var currentSum := 0;
  var count := 0;
  var hashMap := new Dictionary<integer, integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    currentSum += arr[i];

    if currentSum = targetSum then
      count += 1;

    if hashMap.ContainsKey(currentSum - targetSum) then
      count += hashMap[currentSum - targetSum];

    if hashMap.ContainsKey(currentSum) then
      hashMap[currentSum] += 1
    else
      hashMap[currentSum] := 1;
  end;

  Result := count;
end;

function MergeSortedLists(list1, list2: array of integer): array of integer;
begin
  var mergedList := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < list1.Length) and (j < list2.Length) do
  begin
    if list1[i] < list2[j] then
    begin
      mergedList.Add(list1[i]);
      i += 1;
    end
    else
    begin
      mergedList.Add(list2[j]);
      j += 1;
    end;
  end;

  while i < list1.Length do
  begin
    mergedList.Add(list1[i]);
    i += 1;
  end;

  while j < list2.Length do
  begin
    mergedList.Add(list2[j]);
    j += 1;
  end;

  Result := mergedList.ToArray;
end;

