  for var i := 1 to n - 1 do
  begin
    if target[i] <= target[i - 1] then
      dp[i] := dp[i - 1]
    else
      dp[i] := dp[i - 1] + (target[i] - target[i - 1]);
  end;

  Result := dp[n - 1];
end;

