    if not count.ContainsKey(nums[i]) then
      count[nums[i]] := 0;
    count[nums[i]] += 1;
  end;

  var longest := 0;

  foreach var k in count.Keys do
  begin
    if count.ContainsKey(k + 1) then
      longest := Max(longest, count[k] + count[k + 1]);
  end;

  Result := longest;
end;

