function MaxFreq(s: string; maxLetters, minSize, maxSize: integer): integer;
begin
  var table := new Dictionary<string, integer>;

  for var i := 0 to s.Length - minSize do
  begin
    var word := s.Substring(i, minSize);

    if table.ContainsKey(word) then
      table[word] += 1
    else
    begin
      var count := new Dictionary<char, integer>;
      for var j := 0 to word.Length - 1 do
      begin
        if not count.ContainsKey(word[j]) then
          count[word[j]] := 0;
        count[word[j]] += 1;
      end;

      if count.Count <= maxLetters then
        table[word] := 1;
    end;
  end;

  if table.Count > 0 then
    Result := table.Values.Max
  else
    Result := 0;
end;

