function MaxInSubarrays(arr: array of integer; k: integer): array of integer;
begin
  var d := new Queue<integer>;
  var maxList := new List<integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    while (d.Count > 0) and (arr[i] >= arr[d.Peek]) do
      d.Dequeue;

    d.Enqueue(i);

    if i >= k - 1 then
    begin
      if d.Peek = i - k then
        d.Dequeue;

      maxList.Add(arr[d.Peek]);
    end;
  end;

  Result := maxList.ToArray;
end;

