type
  Node = class
    val: integer;
    left, right: Node;

    constructor Create(x: integer; l: Node := nil; r: Node := nil);
    begin
      val := x;
      left := l;
      right := r;
    end;
  end;

function HeightOfTree(root: Node): integer;
begin
  if root = nil then
    Result := -1
  else
  begin
    var leftHeight := HeightOfTree(root.left);
    var rightHeight := HeightOfTree(root.right);
    Result := Max(leftHeight, rightHeight) + 1;
  end;
end;

function ValidateIPv4(ip: string): boolean;
begin
  var parts := ip.Split('.');

  if parts.Length <> 4 then
  begin
    Result := false;
    exit;
  end;

  for var i := 0 to parts.Length - 1 do
  begin
    if not parts[i].All(c -> c.IsDigit) then
    begin
      Result := false;
      exit;
    end;

    if (parts[i].Length > 1) and (parts[i][0] = '0') then
    begin
      Result := false;
      exit;
    end;

    var num := StrToInt(parts[i]);
    if (num < 0) or (num > 255) then
    begin
      Result := false;
      exit;
    end;
  end;

  Result := true;
end;

