function CheckPythagoreanTriplet(nums: array of integer): boolean;
begin
  var numSet := new HashSet<integer>(nums);

  for var i := 0 to nums.Length - 1 do
  begin
    var a := nums[i];
    for var j := i + 1 to nums.Length - 1 do
    begin
      var b := nums[j];
      var cSquared := a * a + b * b;
      var c := Trunc(Sqrt(cSquared));

      if (c * c = Trunc(cSquared)) and numSet.Contains(c) then
      begin
        Result := true;
        exit;
      end;
    end;
  end;

  Result := false;
end;

