function RotateAndFindMax(arr: array of integer; steps: integer; direction: string): integer;
begin
  steps := steps mod arr.Length;
  var rotatedArr: array of integer;

  if direction = 'clockwise' then
    rotatedArr := arr[arr.Length - steps:arr.Length] + arr[0:arr.Length - steps]
  else if direction = 'counterclockwise' then
    rotatedArr := arr[steps:arr.Length] + arr[0:steps]
  else
    raise new System.ArgumentException('Direction must be "clockwise" or "counterclockwise"');

  Result := rotatedArr.Max;
end;

function FindWaysToReachStair(n: integer): integer;
begin
  if n = 1 then
  begin
    Result := 1;
    exit;
  end
  else if n = 2 then
  begin
    Result := 2;
    exit;
  end
  else if n = 3 then
  begin
    Result := 4;
    exit;
  end
  else
  begin
    var a := 1;
    var b := 2;
    var c := 4;

    for var i := 3 to n - 1 do
    begin
      var total := a + b + c;
      a := b;
      b := c;
      c := total;
    end;

    Result := c;
  end;
end;

