function MaxProductWordLength(words: array of string): integer;
begin
  var L := words.Length;
  var occs := new boolean[L, 26];

  for var i := 0 to L - 1 do
    foreach var c in words[i] do
      occs[i, Ord(c) - Ord('a')] := true;

  var sol := 0;

  for var i := 0 to L - 2 do
    for var j := i + 1 to L - 1 do
    begin
      var common := false;

      for var k := 0 to 25 do
      begin
        if occs[i, k] and occs[j, k] then
        begin
          common := true;
          break;
        end;
      end;

      if not common then
        sol := Max(sol, words[i].Length * words[j].Length);
    end;

  Result := sol;
end;

function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
  begin
    Result := false;
    exit;
  end;

  if n <= 3 then
  begin
    Result := true;
    exit;
  end;

  if (n mod 2 = 0) or (n mod 3 = 0) then
  begin
    Result := false;
    exit;
  end;

  var i := 5;
  while i * i <= n do
  begin
    if (n mod i = 0) or (n mod (i + 2) = 0) then
    begin
      Result := false;
      exit;
    end;
    i += 6;
  end;

  Result := true;
end;

function NthFiboPrime(n: integer): integer;
