  var a: BigInteger := 0;
  var b: BigInteger := 1;

  while fiboPrimes.Count < n do
  begin
    (a, b) := (b, a + b);

    if IsPrime(integer(b)) then
      fiboPrimes.Add(integer(b));
  end;

  Result := fiboPrimes[fiboPrimes.Count - 1];
end;

function AreaOverlap(ax1, ay1, ax2, ay2, bx1, by1, bx2, by2: integer): integer;
begin
  var overlapX := Max(0, Min(ax2, bx2) - Max(ax1, bx1));
  var overlapY := Max(0, Min(ay2, by2) - Max(ay1, by1));
  Result := overlapX * overlapY;
end;

function ProductEvenOdd(lst: array of integer): integer;
begin
  var even := 0;
  var odd := 0;
  var foundEven := false;
  var foundOdd := false;

  for var i := 0 to lst.Length - 1 do
  begin
    if (not foundEven) and (lst[i] mod 2 = 0) then
    begin
      even := lst[i];
      foundEven := true;
    end
    else if (not foundOdd) and (lst[i] mod 2 <> 0) then
    begin
      odd := lst[i];
      foundOdd := true;
    end;

    if foundEven and foundOdd then
      break;
  end;

  if foundEven and foundOdd then
    Result := even * odd
  else
    Result := 0;
end;

uses System.Collections.Generic;

function CheckMe(s: string; words: array of string): boolean;
begin
  var wordSet := new HashSet<string>(words);
  var queue := new Queue<integer>;
  var visited := new boolean[s.Length];

  queue.Enqueue(0);

  while queue.Count > 0 do
  begin
    var start := queue.Dequeue;

    if visited[start] then
      continue;

    for var &end := start + 1 to s.Length do
    begin
      if wordSet.Contains(s.Substring(start, &end - start)) then
      begin
        queue.Enqueue(&end);

        if &end = s.Length then
        begin
          Result := true;
          exit;
        end;
      end;
    end;

    visited[start] := true;
  end;

  Result := false;
end;

