function CountSubarrays(nums: array of integer; k: integer): integer;
begin
  var prefixSum := 0;
  var count := 0;
  var subarrayCount := new Dictionary<integer, integer>;
  subarrayCount[0] := 1;

  for var i := 0 to nums.Length - 1 do
  begin
    prefixSum += nums[i];

    if subarrayCount.ContainsKey(prefixSum - k) then
      count += subarrayCount[prefixSum - k];

    if subarrayCount.ContainsKey(prefixSum) then
      subarrayCount[prefixSum] += 1
    else
      subarrayCount[prefixSum] := 1;
  end;

  Result := count;
end;

function Factorial(n: integer): BigInteger;
begin
  Result := 1;
  for var i := 2 to n do
    Result := Result * i;
end;

function IsCatalan(n: integer): BigInteger;
begin
  var numerator := Factorial(2 * n);
  var denominator := Factorial(n) * Factorial(n) * (n + 1);
  Result := numerator div denominator;
end;

procedure GenerateCombinations(lst: array of integer; start: integer; current: List<integer>; n: integer; resultList: List<array of integer>);
begin
  if current.Count = n then
  begin
