    exit;
  end;

  for var i := start to lst.Length - 1 do
  begin
    current.Add(lst[i]);
    GenerateCombinations(lst, i + 1, current, n, resultList);
    current.RemoveAt(current.Count - 1);
  end;
end;

function CombinationsGenerator(lst: array of integer; n: integer): List<array of integer>;
