function MaxProductSubarray(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var prevMin := arr[0];
  var prevMax := arr[0];
  var resultVal := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    if arr[i] < 0 then
    begin
      var temp := prevMin;
      prevMin := prevMax;
      prevMax := temp;
    end;

    prevMax := Max(arr[i], prevMax * arr[i]);
    prevMin := Min(arr[i], prevMin * arr[i]);
    resultVal := Max(resultVal, prevMax);
  end;

  Result := resultVal;
end;

