  while (i < s.Length) and (resultVal < g.Length) do
  begin
    if s[i] >= g[resultVal] then
      resultVal += 1;
    i += 1;
  end;

  Result := resultVal;
end;

function MaxRectArea(heights: array of integer): integer;
begin
  var stack := new Stack<integer>;
  var maxArea := 0;
  var index := 0;

  while index < heights.Length do
  begin
    if (stack.Count = 0) or (heights[stack.Peek] <= heights[index]) then
    begin
      stack.Push(index);
      index += 1;
    end
    else
    begin
      var topOfStack := stack.Pop;
      var area := heights[topOfStack] * (if stack.Count = 0 then index else index - stack.Peek - 1);
      maxArea := Max(maxArea, area);
    end;
  end;

  while stack.Count > 0 do
  begin
    var topOfStack := stack.Pop;
    var area := heights[topOfStack] * (if stack.Count = 0 then index else index - stack.Peek - 1);
    maxArea := Max(maxArea, area);
  end;

  Result := maxArea;
end;

function LongestDupSubstring(S: string): string;
begin
  var res := '';
  var l := 0;
  var r := S.Length - 1;
  var aNum := Ord('a');

  while l <= r do
  begin
    var tmp: string := nil;
    var id := 0;
    var existence := new HashSet<integer>;
    var size := l + (r - l) div 2;
    var tem := Round(Power(26, size - 1));

    for var i := 0 to size - 1 do
      id := id * 26 + (Ord(S[i]) - aNum);

    existence.Add(id);

    for var i := size to S.Length - 1 do
    begin
      var tail := S[i];
      var prevHead := S[i - size];
      id := (id - (Ord(prevHead) - aNum) * tem) * 26 + (Ord(tail) - aNum);

      if existence.Contains(id) then
      begin
        tmp := S.Substring(i - size + 1, size);
        break;
      end;
      existence.Add(id);
    end;

    if tmp <> nil then
    begin
      l := size + 1;
      res := tmp;
    end
    else
      r := size - 1;
  end;

  Result := res;
end;

