function ShortestSubstring(s: string): string;
begin
  var uniqueChars := new HashSet<char>(s);
  var counter := new Dictionary<char, integer>;
  var head := 0;
  var minLen := integer.MaxValue;
  var minStr := '';

  for var tail := 0 to s.Length - 1 do
  begin
    if not counter.ContainsKey(s[tail]) then
      counter[s[tail]] := 0;
    counter[s[tail]] += 1;

    while counter.Count = uniqueChars.Count do
    begin
      var currLen := tail - head + 1;
      if currLen < minLen then
      begin
        minLen := currLen;
        minStr := s.Substring(head, currLen);
      end;

      counter[s[head]] -= 1;
      if counter[s[head]] = 0 then
        counter.Remove(s[head]);
      head += 1;
    end;
  end;

  Result := minStr;
end;

function KthLargestUnique(arr: array of integer; k: integer): integer;
begin
  var uniqueElements := arr.Distinct.ToArray;

  if uniqueElements.Length < k then
  begin
    Result := -1;
    exit;
  end;

  &Array.Sort(uniqueElements);
  &Array.Reverse(uniqueElements);
  Result := uniqueElements[k - 1];
end;

function ClosestNumberDivisible(x, y: integer): integer;
begin
  var quotient := x div y;
  var lower := y * quotient;
  var upper := y * (quotient + 1);

  if x - lower < upper - x then
    Result := lower
  else
    Result := upper;
end;

