function IntegerToHex(num: integer): string;
begin
  if num = 0 then
  begin
    Result := '0';
    exit;
  end;

  var hexChars := '0123456789abcdef';
  var hexString := '';

  while num > 0 do
  begin
    hexString := hexChars[num mod 16] + hexString;
    num := num div 16;
  end;

  Result := hexString;
end;

