function CanJump(nums: array of integer): boolean;
begin
  var &end := 0;
  var n := nums.Length;

  for var i := 0 to n - 1 do
  begin
    if i > &end then
    begin
      Result := false;
      exit;
    end;

    if i = n - 1 then
    begin
      Result := true;
      exit;
    end;

    &end := Max(&end, i + nums[i]);
  end;

  Result := true;
end;

function FindDuplicateMissing(arr: array of integer): (integer, integer);
begin
  var count := new Dictionary<integer, integer>;
  var n := arr.Length;
  var duplicate := -1;
  var missing := -1;

  for var i := 0 to arr.Length - 1 do
  begin
    if count.ContainsKey(arr[i]) then
      count[arr[i]] += 1
    else
      count[arr[i]] := 1;
  end;

  for var i := 1 to n do
  begin
    if count.ContainsKey(i) then
    begin
      if count[i] = 2 then
        duplicate := i;
    end
    else
      missing := i;
  end;

  Result := (duplicate, missing);
end;

function WaysToChange(amount: integer; coins: array of integer): integer;
