function SmallestRepeatingUnit(s: string): string;
begin
  var length := s.Length;

  for var i := 1 to length div 2 do
  begin
    if length mod i = 0 then
    begin
      var _unit := s.Substring(0, i);
      var repeated := '';

      for var j := 1 to length div i do
        repeated += _unit;

      if repeated = s then
      begin
        Result := _unit;
        exit;
      end;
    end;
  end;

  Result := s;
end;

