    head: Node;

    constructor;
    begin
      head := nil;
    end;

    procedure Reverse;
    begin
      var prev: Node := nil;
      var current := head;
      while current <> nil do
      begin
        var next := current.next; 
        current.next := prev;  
        prev := current;       
        current := next;        
      end;
      head := prev;  
    end;


